import{_ as e,o as a,c as r,a4 as o}from"./chunks/framework.CAgiNEKA.js";const c=JSON.parse('{"title":"Claude Opus 4.8 深度点评：更诚实的旗舰，Agent 时代的新基准","description":"","frontmatter":{},"headers":[],"relativePath":"ai-knowledge/claude-opus-4-8-review.md","filePath":"ai-knowledge/claude-opus-4-8-review.md","lastUpdated":1780053872000}'),n={name:"ai-knowledge/claude-opus-4-8-review.md"};function s(d,t,l,h,i,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="claude-opus-4-8-深度点评-更诚实的旗舰-agent-时代的新基准" tabindex="-1">Claude Opus 4.8 深度点评：更诚实的旗舰，Agent 时代的新基准 <a class="header-anchor" href="#claude-opus-4-8-深度点评-更诚实的旗舰-agent-时代的新基准" aria-label="Permalink to &quot;Claude Opus 4.8 深度点评：更诚实的旗舰，Agent 时代的新基准&quot;">​</a></h1><blockquote><p>本文基于 Anthropic 官方发布信息及多方技术媒体评测整理，原文参考：</p><ul><li><a href="https://anthropic.com/news/claude-opus-4-8" target="_blank" rel="noreferrer">Anthropic 官方公告</a></li><li><a href="https://techcrunch.com/2026/05/28/anthropic-releases-opus-4-8-with-new-dynamic-workflow-tool/" target="_blank" rel="noreferrer">TechCrunch 报道</a></li><li><a href="https://llm-stats.com/blog/research/claude-opus-4-8-launch" target="_blank" rel="noreferrer">llm-stats 基准详情</a></li><li><a href="https://simonwillison.net/2026/May/28/claude-opus-4-8/" target="_blank" rel="noreferrer">Simon Willison 独立评测</a></li></ul><p>原文观点仅代表作者个人意见。</p></blockquote><hr><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>2026 年 5 月 28 日，Anthropic 正式发布 Claude Opus 4.8，距离上一版 Opus 4.7 仅 41 天，创下 Opus 系列最快迭代纪录。这次更新没有颠覆性的参数突破，Anthropic 自己也坦言这是&quot;modest but tangible improvement（适度但切实的提升）&quot;。但正是这份罕见的诚实，以及新版本在 <strong>编程可靠性、Agent 长任务、诚实度对齐</strong> 三个维度上的扎实进步，让它值得深入了解。</p><hr><h2 id="测评场景汇总" tabindex="-1">测评场景汇总 <a class="header-anchor" href="#测评场景汇总" aria-label="Permalink to &quot;测评场景汇总&quot;">​</a></h2><h3 id="_1-编程能力" tabindex="-1">1. 编程能力 <a class="header-anchor" href="#_1-编程能力" aria-label="Permalink to &quot;1. 编程能力&quot;">​</a></h3><p>测试模型在实际代码任务中的准确性与自我纠错能力。</p><p><strong>结论：</strong> Opus 4.8 在 SWE-bench Verified 上达到 <strong>88.6%</strong>（4.7 为 87.6%），SWE-bench Pro 提升更明显，从 64.3% 跳至 <strong>69.2%</strong>。最关键的是：模型对自己写出的有缺陷代码，<strong>漏报率降低了约 4 倍</strong>——也就是说它更会&quot;检查自己的作业&quot;了。</p><hr><h3 id="_2-数学推理" tabindex="-1">2. 数学推理 <a class="header-anchor" href="#_2-数学推理" aria-label="Permalink to &quot;2. 数学推理&quot;">​</a></h3><p>测试复杂数学题的推理与解题能力。</p><p><strong>结论：</strong> USAMO 2026 基准上，Opus 4.8 得分 <strong>96.7%</strong>，而 Opus 4.7 仅 69.3%，这是 Opus 系列单版本迭代中最大的数学跳跃。GPQA Diamond（研究生级科学题）维持在 <strong>93.6%</strong>，与 4.7 持平。</p><hr><h3 id="_3-agent-长任务-dynamic-workflows" tabindex="-1">3. Agent 长任务 / Dynamic Workflows <a class="header-anchor" href="#_3-agent-长任务-dynamic-workflows" aria-label="Permalink to &quot;3. Agent 长任务 / Dynamic Workflows&quot;">​</a></h3><p>测试模型在多步骤、跨文件、长时间自主运行任务中的稳定性。</p><p><strong>结论：</strong> 同步发布的 <strong>Dynamic Workflows</strong> 功能允许 Claude Code 调度数百个并行子 Agent，官方案例是&quot;从启动到合并，跨数十万行代码完成整库迁移&quot;。MCP-Atlas 基准从 77.3% 升至 <strong>82.2%</strong>，长任务场景显著增强。</p><hr><h3 id="_4-计算机操作-computer-use" tabindex="-1">4. 计算机操作（Computer Use） <a class="header-anchor" href="#_4-计算机操作-computer-use" aria-label="Permalink to &quot;4. 计算机操作（Computer Use）&quot;">​</a></h3><p>测试模型读取屏幕截图、操作 GUI 完成任务的能力。</p><p><strong>结论：</strong> OSWorld-Verified 达到 <strong>83.4%</strong>，是目前市场上 Computer Use 能力最强的模型，超过 GPT-5.5 和 Gemini 3.1 Pro。</p><hr><h3 id="_5-诚实度与对齐" tabindex="-1">5. 诚实度与对齐 <a class="header-anchor" href="#_5-诚实度与对齐" aria-label="Permalink to &quot;5. 诚实度与对齐&quot;">​</a></h3><p>测试模型是否会在不确定时主动承认、而非编造答案。</p><p><strong>结论：</strong> 这是本次更新最有特色的方向。Anthropic 报告显示，Opus 4.8 在六款同级模型中<strong>幻觉错误率最低</strong>——主要策略是&quot;遇到不确定问题时选择弃答，而非猜测作答&quot;。早期测试者反馈：模型更愿意标注自己的不确定性，减少了无依据断言。</p><hr><h3 id="_6-费用对比" tabindex="-1">6. 费用对比 <a class="header-anchor" href="#_6-费用对比" aria-label="Permalink to &quot;6. 费用对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>Opus 4.7</th><th>Opus 4.8</th></tr></thead><tbody><tr><td>输入价格</td><td>$5 / 百万 Token</td><td>$5 / 百万 Token（不变）</td></tr><tr><td>输出价格</td><td>$25 / 百万 Token</td><td>$25 / 百万 Token（不变）</td></tr><tr><td>Fast Mode</td><td>$30 / $150（研究预览）</td><td>$10 / $50（降价 3 倍！）</td></tr><tr><td>上下文窗口</td><td>100 万 Token</td><td>100 万 Token（不变）</td></tr><tr><td>最大输出</td><td>128K Token</td><td>128K Token（不变）</td></tr></tbody></table><p>Fast Mode 价格直降 3 倍，是本次最实惠的变化。</p><hr><h2 id="原文总结" tabindex="-1">原文总结 <a class="header-anchor" href="#原文总结" aria-label="Permalink to &quot;原文总结&quot;">​</a></h2><p>Opus 4.8 是一次<strong>务实的工程升级</strong>，而非营销驱动的大版本发布。它的核心逻辑是：在 Agent 任务大规模落地的当下，比&quot;更聪明&quot;更重要的是&quot;更可靠、更诚实&quot;。</p><p>值得特别关注的是：Anthropic 同步预告了下一代旗舰模型 <strong>Mythos</strong> 即将到来（&quot;数周内&quot;），Opus 4.x 系列可能接近尾声。如果你在评估是否现在接入 Opus 4.8，答案是肯定的——它是当前最强的 Computer Use 模型，也是 Agent 编程任务的新基准。</p><hr><h2 id="🐼-熊猫算力视角-怎么选适合你的模型" tabindex="-1">🐼 熊猫算力视角：怎么选适合你的模型？ <a class="header-anchor" href="#🐼-熊猫算力视角-怎么选适合你的模型" aria-label="Permalink to &quot;🐼 熊猫算力视角：怎么选适合你的模型？&quot;">​</a></h2><h3 id="各模型擅长场景" tabindex="-1">各模型擅长场景 <a class="header-anchor" href="#各模型擅长场景" aria-label="Permalink to &quot;各模型擅长场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>最适合场景</th></tr></thead><tbody><tr><td><strong>Claude Opus 4.8</strong></td><td>Agent 长任务、大型代码库迁移、需要高可靠性的生产环境</td></tr><tr><td><strong>Claude Sonnet 4.6</strong></td><td>日常对话、内容创作、性价比优先的 API 调用</td></tr><tr><td><strong>GPT-5.4</strong></td><td>通用对话、图像理解（需稳定多模态时）</td></tr><tr><td><strong>Gemini 3.1 Pro</strong></td><td>图表理解、文档 QA、视觉推理场景</td></tr></tbody></table><h3 id="熊猫算力平台价格" tabindex="-1">熊猫算力平台价格 <a class="header-anchor" href="#熊猫算力平台价格" aria-label="Permalink to &quot;熊猫算力平台价格&quot;">​</a></h3><p>通过熊猫算力接入 Claude Opus 4.8，享受与官方同步的最新模型，无需海外信用卡，国内直连稳定访问。<br> 👉 <a href="https://pandatoken.cn" target="_blank" rel="noreferrer">查看最新定价 →</a></p>',40)])])}const g=e(n,[["render",s]]);export{c as __pageData,g as default};
